import numpy as np
from sklearn.decomposition import PCA
import matplotlib.pyplot as plt

def task_func(data, save_plot=False, plot_path=None):
    if save_plot and not plot_path:
        raise ValueError("plot_path must be provided when save_plot is True.")

    if data is None:
        raise ValueError("data must not be None.")

    data = list(data)
    if len(data) == 0:
        raise ValueError("data must contain at least one object with coordinates.")

    try:
        objects, coordinates = zip(*data)
    except ValueError as exc:
        raise ValueError("data must be an iterable of (object, 3D_coordinates) pairs.") from exc

    coordinates = np.asarray(coordinates, dtype=float)

    if coordinates.ndim != 2 or coordinates.shape[1] != 3:
        raise ValueError("Each coordinate must contain exactly three numeric values.")

    if not np.all(np.isfinite(coordinates)):
        raise ValueError("Coordinates must contain only finite numeric values.")

    n_samples, n_features = coordinates.shape
    n_components = min(2, n_samples, n_features)

    if n_components == 0:
        coordinates_2d = np.empty((n_samples, 2), dtype=float)
    elif n_samples == 1:
        coordinates_2d = np.zeros((1, 2), dtype=float)
    else:
        reduced = PCA(n_components=n_components).fit_transform(coordinates)
        if n_components < 2:
            coordinates_2d = np.zeros((n_samples, 2), dtype=float)
            coordinates_2d[:, :n_components] = reduced
        else:
            coordinates_2d = reduced

    fig, ax = plt.subplots()
    ax.scatter(coordinates_2d[:, 0], coordinates_2d[:, 1])

    for obj, (x, y) in zip(objects, coordinates_2d):
        ax.annotate(str(obj), (x, y))

    ax.set_xlabel("Principal Component 1")
    ax.set_ylabel("Principal Component 2")
    ax.set_title("2D PCA Projection")
    fig.tight_layout()

    if save_plot:
        fig.savefig(plot_path)
        plt.close(fig)
        return coordinates_2d

    return coordinates_2d, ax
